const raw = ($json.response || '').replace(/<think>[\s\S]*?<\/think>/g, '').trim();
const { 
  thinking,
  context,
  selector,
  response,
  ...article
} = $json;

return {
  json: {
    ...article,
    summary: raw
  }
};

// Collect all incoming articles
const articles = $input.all().map(item => item.json);

// Helper to build article text
const formatArticle = (article, index) => {

  // Build source list
  const sourceList =
    Array.isArray(article.sourceNames) && article.sourceNames.length
      ? article.sourceNames.join(', ')
      : (article.source || 'Unknown source');

  return [
    `${index + 1}. **${article.title}** (${sourceList})`,
    article.summary
  ].join('\n');
};

// --------------------------------------------------
// GLOBAL SUMMARY (all articles)
// --------------------------------------------------
const summary = articles
  .map((article, index) => formatArticle(article, index))
  .join('\n\n');

// --------------------------------------------------
// SUMMARIES BY PLACE
// --------------------------------------------------
// Group articles by place
const groupedByPlace = articles.reduce((acc, article) => {
  const place = article.place || 'Other';

  if (!acc[place]) {
    acc[place] = [];
  }

  acc[place].push(article);

  return acc;
}, {});

// Build summaries per place
const summariesByPlace = Object.fromEntries(
  Object.entries(groupedByPlace).map(([place, placeArticles]) => {

    const placeSummary = placeArticles
      .map((article, index) => formatArticle(article, index))
      .join('\n\n');

    return [place, placeSummary];
  })
);

return [{
  json: {
    // Full summary with everything
    summary,

    // Separate summaries by place
    summariesByPlace
  }
}];

