const raw = ($json.response || '').replace(/<think>[\s\S]*?<\/think>/g, '').trim();
let translated;
try {
  translated = JSON.parse(raw);
} catch (error) {
  translated = {};
}

const originalTitle = $json.originalTitle || $json.title || '';
const originalSnippet = $json.originalSnippet || $json.snippet || '';
const translatedTitle = translated.title || $json.translatedTitle || $json.title;
const translatedSnippet = translated.snippet || $json.translatedSnippet || $json.snippet;

return {
  json: {
    ...$json,
    originalTitle,
    originalSnippet,
    translatedTitle,
    translatedSnippet,
    title: translatedTitle,
    snippet: translatedSnippet,
  }
};

/**
 * Merge and filter all articles
 * Return the array of articles directly
 */
return $input.all()
  .flatMap(item => item.json.articles || [])
  .filter(article => article.title?.trim() && article.link?.trim())
  .map(article => ({
    json: article,
  }));

const raw = ($json.response || '').replace(/<think>[\s\S]*?<\/think>/g, '').trim();
return {
  json: {
    ...$json,
    overview: raw
  }
};

const stripThink = (text) =>
  (text || '').replace(/<think>[\s\S]*?<\/think>/g, '').trim();

const articles = $input.all().map(item => item.json);

const now = new Date();
const pad = n => String(n).padStart(2, '0');
const date = now.getFullYear() + '-' + pad(now.getMonth() + 1) + '-' + pad(now.getDate());

return [{
  json: {
    date,
    articles: articles.map(a => ({ ...a, summary: stripThink(a.summary || '') }))
  }
}];

const now = new Date();
const pad = n => String(n).padStart(2, '0');
const date = now.getFullYear() + '-' + pad(now.getMonth() + 1) + '-' + pad(now.getDate());

const overviewsHtml = $json.overviewsHtml || '';
const articlesHtml  = $json.articlesHtml  || '';
const overviewsText = $json.overviewsText || '';
const articlesText  = $json.articlesText  || '';
const articleCount  = $json.articleCount  || 0;

const styles =
  'body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;' +
    'max-width:760px;margin:0 auto;padding:24px 16px;color:#1a1a1a;line-height:1.65}' +
  'h1{font-size:1.5em;color:#111;border-bottom:2px solid #ddd;padding-bottom:8px;margin-bottom:16px}' +
  'h2{font-size:1.2em;color:#222;margin-top:24px;margin-bottom:8px}' +
  'h3{font-size:1em;color:#333;margin-top:16px;margin-bottom:4px}' +
  '.meta{color:#666;font-size:.88em;margin:2px 0 8px}' +
  '.stats{color:#555;font-size:.85em;margin:4px 0 12px;font-style:italic}' +
  '.article{margin-bottom:20px}' +
  'hr{border:none;border-top:1px solid #e0e0e0;margin:16px 0}' +
  'hr.s-sep{border-top:2px solid #c0c0c0;margin:28px 0}' +
  'hr.a-sep{border-top:1px dashed #d0d0d0;margin:12px 0}' +
  'p{margin:4px 0 10px}' +
  'a{color:#2563eb;text-decoration:none}' +
  'strong{font-weight:600}';

const html =
  '<!DOCTYPE html><html><head>' +
  '<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">' +
  '<style>' + styles + '</style></head><body>' +
  overviewsHtml + '<hr class="s-sep">' + articlesHtml +
  '</body></html>';

const text = overviewsText + '\n\n---\n\n' + articlesText;

return [{
  json: { ...$json, html, text, subject: 'Daily News Briefing - ' + date + ' (' + articleCount + ' articles)' },
  binary: $input.first()?.binary ?? {}
}];

const { date, articles } = $json;

const getUnique = (vals) => [...new Set((vals || []).filter(Boolean))];

const groupedByPlace = articles.reduce((acc, a) => {
  const place = a.place || 'Other';
  if (!acc[place]) acc[place] = [];
  acc[place].push(a);
  return acc;
}, {});

const fmtArticle = (a, i) => {
  const sources = Array.isArray(a.sources) && a.sources.length
    ? a.sources
    : [{ name: a.source || 'Unknown', link: a.link || '', pubDate: a.pubDate || '' }];

  const srcLine = sources
    .map(s => s.link ? '[' + s.name + '](' + s.link + ')' : s.name)
    .join(', ');
  const dateLine = getUnique(sources.map(s => s.pubDate || a.pubDate)).join(', ');
  const meta = [
    srcLine   ? '**Sources:** ' + srcLine   : '',
    dateLine  ? '**Dates:** '   + dateLine  : ''
  ].filter(Boolean).join('  \n');

  return ['### ' + (i + 1) + '. ' + (a.title || 'Untitled'), meta, '', a.summary || ''].join('\n');
};

const placesMd = Object.entries(groupedByPlace)
  .map(([place, arts]) =>
    ['## ' + place, '', arts.map(fmtArticle).join('\n\n---\n\n')].join('\n'))
  .join('\n\n---\n\n');

return [{
  json: {
    filename: 'news-articles-' + date + '.md',
    articlesText: '# Daily News Articles — ' + date + '\n\n' + placesMd,
    articleCount: articles.length
  }
}];

const { date, articles } = $json;

const esc = s => String(s || '')
  .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const getUnique = (vals) => [...new Set((vals || []).filter(Boolean))];

if (articles.length === 0) {
  return [{
    json: {
      articlesHtml: '<section id="articles"><h1>Daily News Articles — ' + date + '</h1><p><em>No articles found today.</em></p></section>',
      articleCount: 0
    }
  }];
}

const groupedByPlace = articles.reduce((acc, a) => {
  const place = a.place || 'Other';
  if (!acc[place]) acc[place] = [];
  acc[place].push(a);
  return acc;
}, {});

const sourceCounts = articles.reduce((acc, a) => {
  const src = a.source || 'Unknown';
  acc[src] = (acc[src] || 0) + 1;
  return acc;
}, {});
const statsLine = Object.entries(sourceCounts)
  .map(([src, n]) => esc(src) + ' (' + n + ')')
  .join(' &middot; ');
const statsHtml = '<p class="stats">' + articles.length + ' articles from: ' + statsLine + '</p>';

const fmtArticle = (a, i) => {
  const sources = Array.isArray(a.sources) && a.sources.length
    ? a.sources
    : [{ name: a.source || 'Unknown', link: a.link || '', pubDate: a.pubDate || '' }];

  const srcLinks = sources
    .map(s => s.link ? '<a href="' + esc(s.link) + '">' + esc(s.name) + '</a>' : esc(s.name))
    .join(', ');
  const dates = getUnique(sources.map(s => s.pubDate || a.pubDate)).join(', ');

  const metaParts = [];
  if (srcLinks) metaParts.push('<strong>Sources:</strong> ' + srcLinks);
  if (dates)    metaParts.push('<strong>Date:</strong> '    + esc(dates));

  return '<div class="article">' +
    '<h3>' + (i + 1) + '. ' + esc(a.title || 'Untitled') + '</h3>' +
    (metaParts.length ? '<p class="meta">' + metaParts.join(' &middot; ') + '</p>' : '') +
    '<p>' + esc(a.summary || '').replace(/\n/g, '<br>') + '</p>' +
    '</div>';
};

const placesHtml = Object.entries(groupedByPlace)
  .map(([place, arts]) =>
    '<section class="place"><h2>' + esc(place) + '</h2>' +
    arts.map(fmtArticle).join('<hr class="a-sep">') +
    '</section>')
  .join('<hr class="s-sep">');

return [{
  json: {
    articlesHtml:
      '<section id="articles">' +
      '<h1>Daily News Articles — ' + date + '</h1>' +
      statsHtml +
      placesHtml +
      '</section>',
    articleCount: articles.length
  }
}];

const { date, globalOverview, overviewsByPlace } = $json;

const esc = s => String(s || '')
  .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

const placesHtml = Object.entries(overviewsByPlace)
  .map(([place, overview]) => {
    if (!overview) return '';
    return '<section class="place-overview">' +
      '<h2>' + esc(place) + '</h2>' +
      '<p>' + esc(overview).replace(/\n/g, '<br>') + '</p>' +
      '</section>';
  })
  .filter(Boolean)
  .join('<hr class="s-sep">');

return [{
  json: {
    overviewsHtml:
      '<section id="overviews">' +
      '<h1>Daily News Overviews — ' + date + '</h1>' +
      '<section class="global">' +
      '<h2>Global Overview</h2>' +
      '<p>' + esc(globalOverview).replace(/\n/g, '<br>') + '</p>' +
      '</section>' +
      (placesHtml ? '<hr class="s-sep"><h2>Place Overviews</h2>' + placesHtml : '') +
      '</section>'
  }
}];

return {
  json: {
    response: ($json.response || '').replace(/<think>[\s\S]*?<\/think>/g, '').trim()
  }
};

const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const { articles } = $json;

return articles.map(a => {
  const sources = Array.isArray(a.sources) && a.sources.length
    ? a.sources
    : [{ name: a.source || 'Unknown', link: a.link || '' }];

  const srcLine = sources
    .map(s => s.link ? '<a href="' + esc(s.link) + '">' + esc(s.name) + '</a>' : esc(s.name))
    .join(', ');

  const parts = [
    '📄 <b>' + esc(a.title || 'Untitled') + '</b>',
    '📍 ' + esc(a.place || '') + ' · ' + srcLine,
    '',
    esc(a.summary || '')
  ];

  const text = parts.join('\n');
  return { json: { telegramText: text.length > 4096 ? text.substring(0, 4090) + '…' : text } };
});

const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const { date, globalOverview, overviewsByPlace } = $json;

const parts = [
  '📰 <b>Daily News — ' + date + '</b>',
  '',
  '<b>🌍 Global Overview</b>',
  esc(globalOverview)
];

for (const [place, overview] of Object.entries(overviewsByPlace || {})) {
  if (!overview) continue;
  parts.push('');
  parts.push('<b>📍 ' + esc(place) + '</b>');
  parts.push(esc(overview));
}

const text = parts.join('\n');
return [{ json: { telegramText: text.length > 4096 ? text.substring(0, 4090) + '…' : text } }];
